\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[
\sqrt{\frac{1}{\sigma_*}} - \sqrt{\frac{1}{\sigmainit}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*} 
+ C\sqrt{2\gamma_{\rm inc}L_f}\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}. \label{N-def}
\end{align}

\begin{equation}\label{bar-sigma-def}
\bar\sigma = \left\{
\begin{array}{ll}
\ds
\frac{\theta}{1+\sqrt{2}\beta}
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
\ep^{\frac{\rho-2}{\rho-1}}
& (\text{if } \rho \geq 2),\\[3truemm]
\ds
\frac{\theta}{1+\sqrt{2}\beta}
\kappa^{\frac{2}{\rho}}\left(\frac{L_f}{L_{\min}}+1\right)^{-1}(\varphi(\xinit)-\varphi^*)^{-\frac{2-\rho}{\rho}}
& (\text{if } 1\leq \rho<2).
\end{array}
\right.
\end{equation}

\begin{lemma}\label{lem:HEB}
Let $\varphi:\E\to\RR\cup\{+\infty\}$ be a proper, lower-semicontinuous, and convex function.
For $x_0 \in \E$, suppose that $\varphi$ satisfies the H\"olderian error bound condition \eqref{HEB} with coefficient $\kappa > 0$ and exponent $\rho \geq 1$.
Then, for every $x \in \lev_{\varphi}(\varphi(x_0))\setminus X^*$, we have
the inequalities
\begin{equation}\label{Loj-ineq}
\kappa \dist(x,X^*)^{\rho-1} \leq \inf\{\norm{g}:g \in \partial\varphi(x)\},\quad
\kappa^{\frac{1}{\rho}} (\varphi(x)-\varphi^*)^{\frac{\rho-1}{\rho}} \leq \inf\{\norm{g}:g \in \partial\varphi(x)\}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:reg}
\begin{enumerate}[(i)]
\item $\varphi_\sigma(x) \leq \varphi_\sigma(x_0)$ implies $\varphi(x) \leq \varphi(x_0)$.
\item $\norm{x_0-x_\sigma^*} \leq \dist(x_0,X^*)$.
\item We have $\norm{g_L(y)-g_L^\sigma(y)} \leq  \sigma\norm{y-x_0}$ for any $y \in \E$.
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:APG-iter-L}
The condition $\eqref{APG-iter-test}$ of $\APGIter$ holds whenever $L\geq L_f$.
\end{lemma}

\begin{proof}
The first condition \eqref{APG-iter-test-a} is satisfied since $f$ is $L$-smooth (e.g., see \cite[Theorem 2.1.5]{Nes04}).
Since $f_\sigma$ is $(L_f+\sigma)$-smooth, the second one \eqref{APG-iter-test-b} holds if $L\geq L_f$ by Lemma~\ref{lem:gmap} (v).
The third one \eqref{APG-iter-test-c} can be verified again by Lemma~\ref{lem:gmap} (v): If $L\geq L_f$, we have
$
\varphi(T_L(z)) \leq m_L(z;T_L(z)) \leq \varphi(z),
$
where the second inequality follows from
\begin{equation}\label{mL-leq-phi}
m_L(z;T_L(z))=\min_{x \in \E}\left\{f(z)+\innprod{\nabla{f}(z)}{x-z}+\varPsi(x)+\frac{L}{2}\norm{x-z}^2\right\} \stackrel{x=z}{\leq}
f(z)+\varPsi(z)=\varphi(z).
\end{equation}
\end{proof}

\begin{proof}
Since the condition \eqref{PG-iter-test} ensures
$\varphi(T_{M_k}(x_k))\leq m_{M_k}(x_k;T_{M_k}(x_k))\leq \varphi(x_k)$
(recall \eqref{mL-leq-phi} for the second inequality), we conclude (i).
The assertion (ii) can be verified in the same way as Lemma~\ref{lem:APG-iter-LS-compl}.
\end{proof}

\begin{theorem}\label{thm:AdaAPG}
In $\AdaAPG$, let $N$ be the total number of executions of $\APGIter$.
Denote
\begin{equation}\label{sigma-th}
\sigma(x_0,\ep):=\frac{\ep}{(1+\sqrt{2}\beta)\dist(x_0,X^*)},
\end{equation}
where we let $\sigma(x_0,\ep):=+\infty$ when $x_0 \in X^*$.
Then, the following assertions hold.
\begin{enumerate}[(i)]
\item
The algorithm terminates at the $j$-th outer loop whenever
$\sigma_j \leq \sigma(x_0,\ep)$.
Moreover, we have ${\sigma_j \geq \sigma(x_0,\ep)/\gamma_{\rm reg}}$ for all $j>0$.
%\begin{equation}\label{sigma-j-lb}
%\sigma_j \geq \sigma(x_0,\ep)/\gamma_{\rm reg},\quad \forall j>0.
%\end{equation}

\item
Suppose that the algorithm terminates at $j=\ell$ for some $\ell \geq 0$.
Then, $N$ is at most
\begin{align*}
&\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\sigma_\ell}} - \sqrt{\frac{1}{\sigma_0}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell}+ \left(1+\log_{\gamma_{\rm reg}}\frac{\sigma_0}{\sigma_\ell}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell}\right).
\end{align*}
%
\item
If $\sigma_0\leq \sigma(x_0,\ep)$, then
$
N \leq 2+ \left(\sqrt{\frac{2\gamma_{\rm inc}L_f}{\sigma_0}}+1\right)\log\frac{\gamma_{\rm inc}L_f+\sigma_0}{\beta\sigma_0}.
$

%
\item
If $\sigma_0 \geq \sigma(x_0,\ep)$, then $N$ is at most
\begin{align}
&\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\gamma_{\rm reg}\sqrt{\frac{1}{\sigma(x_0,\ep)}} - \sqrt{\frac{1}{\sigma_0}} \right]\log\left(\frac{\gamma_{\rm reg}\gamma_{\rm inc}L_f}{\beta\sigma(x_0,\ep)}+\frac{1}{\beta}\right) \nonumber\\
&+ \left(2+\log_{\gamma_{\rm reg}}\frac{ \sigma_0}{\sigma(x_0,\ep)}\right)\left[2+\log\left(\frac{\gamma_{\rm reg}\gamma_{\rm inc}L_f}{\beta\sigma(x_0,\ep)}+\frac{1}{\beta}\right)\right] \nonumber\\
=~&
O\left(\sqrt{\frac{L_f\dist(x_0,X^*)}{\ep}}\log \frac{L_f\dist(x_0,X^*)}{\ep} + \log \frac{\sigma_0 \dist(x_0,X^*)}{\ep} \log \frac{L_f\dist(x_0,X^*)}{\ep}\right).
\label{AdaAPG-compl-O}
\end{align}
\end{enumerate}
\end{theorem}

\begin{lemma}\label{lem:rAdaAPG-base}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds.
In the execution of $\rAdaAPG$, the following assertions hold.
\begin{enumerate}[(i)]
\item $\outerL{t},\outerM{t} \in [L_{\min},\gamma_{\rm inc}L_f]$ for all $t\geq 0$.
\item $\varphi(\outerXplus{t+1}) \leq \varphi(\outerXplus{t}) \leq \cdots \leq \varphi(\outerXplus{0}) \leq \varphi(\xinit)$ for all $t\geq 0$.
\item $t \leq \log_{1/\theta}\dfrac{\norm{g_{\outerM{0}}(\xinit)}}{\norm{g_{\outerM{t}}(\outerXinit{t})}}$ for each $t\geq 0$.
\item Whenever $\outerXplus{t} \not\in X^*$, we have
\begin{equation}\label{rAdaAPG-dist-bound}
\dist(\outerXplus{t},X^*)^{\rho-1} \leq \frac{1}{\kappa}\left(\frac{L_f}{L_{\min}}+1\right)\norm{g_{\outerM{t}}(\outerXinit{t})},
\end{equation}
\begin{equation}\label{rAdaAPG-obj-bound}
(\varphi(\outerXplus{t})-\varphi^*)^{\rho-1} \leq \frac{1}{\kappa}\left(\frac{L_f}{L_{\min}}+1\right)^\rho\norm{g_{\outerM{t}}(\outerXinit{t})}^\rho.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:rAdaAPG-sigma}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds.
Suppose that $\rAdaAPG$ terminated with the stopping criterion at the $(T+1)$-th outer loop for some $T\geq 0$.
Let $\bar\sigma$ be defined by \eqref{bar-sigma-def}.
\begin{enumerate}[(i)]
\item
For each $t=0,\ldots,T$, we have
$$
\outersigma{t+1}
\left\{
\begin{array}{ll}
=\outersigma{t}&(\outersigma{t}\leq \sigma(\outerXplus{t},\ep^{(t)})),\\
\geq\sigma(\outerXplus{t},\ep^{(t)})/\gamma_{\rm reg}&(\text{otherwise}),
\end{array}
\right.
$$
where $\sigma(\cdot,\cdot)$ is defined by \eqref{sigma-th}. 

\item It follows that $\sigma(\outerXplus{t},\ep^{(t)}) \geq \bar\sigma$ for all $t=0,\ldots,T$.
%\begin{equation}\label{sigma-th-const}
%\sigma(\outerXplus{t},\ep^{(t)}) \geq \bar\sigma, \quad t=0,\ldots,T.
%\end{equation}
When $\rho \geq 2$, we further obtain
\begin{equation}\label{sigma-th-t}
\sigma(\outerXplus{t},\ep^{(t)}) \geq \frac{\theta^{\frac{1}{\rho-1}}}{1+\sqrt{2}\beta}\cdot
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
(\ep^{(t)})^{\frac{\rho-2}{\rho-1}}
 \geq \bar\sigma,
\end{equation}
for each $t=0,\ldots,T$.
\item
For each $t=0,\ldots,T+1$, we obtain
$$
\outersigma{t} \left\{
\begin{array}{ll}
=\sigmainit & (\sigmainit \leq \bar\sigma),\\
\geq\bar\sigma/\gamma_{\rm reg} & (\text{otherwise}).
\end{array}
\right.
$$
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:rAdaAPG-sigma-2}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds with $\rho >2$.
Suppose that $\rAdaAPG$ terminated with the stopping criterion at the $(T+1)$-th outer loop for some $T\geq 0$.
If $\sigmainit \geq \bar\sigma$ holds for $\bar\sigma$  defined by \eqref{bar-sigma-def},
then there exists $t_0 \in \{0,\ldots,T+1\}$ such that the following conditions hold, where
$
\sigma_*^{(0)}:=\frac{\theta}{1+\sqrt{2}\beta}\cdot
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
\|g_{\outerM{0}}(\xinit)\|^{\frac{\rho-2}{\rho-1}}.
$
\begin{align}
\text{(i)\qquad} & \outersigma{0}=\cdots=\outersigma{t_0}. \label{sigma-bound-rho>2-1}\\
\text{(ii)\qquad} & \outersigma{t+1} \geq \theta^{-\frac{\rho-2}{\rho-1}(T-t)} \bar\sigma/\gamma_{\rm reg},\quad t=t_0,\ldots,T.\label{sigma-bound-rho>2-2}\\
\text{(iii)\qquad} & t_0 \leq 1+\frac{\rho-1}{\rho-2}\log_{1/\theta}\frac{\sigma_*^{(0)}}{\min(\sigmainit,\sigma_*^{(0)})}.\label{sigma-bound-rho>2-3}\\
\text{(iv)\qquad} & \theta^{\frac{\rho-2}{\rho-1}(T-t_0)} \geq {\bar\sigma}/{\outersigma{0}}.\label{sigma-bound-rho>2-4}
\end{align}

\end{lemma}

