\begin{definition}
Fix $x_0 \in \E$.
We say that $\varphi$ satisfies the \emph{H\"olderian error bound condition} with coefficient $\kappa > 0$ and exponent $\rho \geq 1$ if
\begin{equation}\label{HEB}
\varphi(x)-\varphi^* \geq \kappa\dist(x,X^*)^\rho,\quad \forall x\in \lev_{\varphi}(\varphi(x_0)),
\end{equation}
where $\lev_{\varphi}(\gamma)=\{x \in \E \mid \varphi(x)\leq \gamma\}$.
\end{definition}

\begin{algorithm}[t]
\caption{
Accelerated Proximal Gradient Iteration
\newline
$\{x_{k+1},\psi_{k+1},M_k,L_{k+1},A_{k+1}\} \leftarrow \APGIter_\sigma(x_k,\psi_k,L_k,A_k)$}
\label{APG-iter}
\textbf{Parameters:} $\gamma_{\rm inc}>1$, $\gamma_{\rm dec}\geq 1$, $L_{\min} \in  ]0,L_f]$.\\
\textbf{Input:} $\sigma>0$, $x_k \in \E$, $\psi_k:\E\to\RR\cup\{+\infty\}$, $L_k>0$, $A_k\geq 0$.
\begin{algorithmic}[1]
\State Compute $v_{k}:=\argmin_{x\in \E} \psi_{k}(x)$\quad (cf. \eqref{APG-iter-v_k-formula}). \label{APG-iter-vk}
\State Set $L:=L_k/\gamma_{\rm inc}$.
\Repeat \label{APG-iter-loop-s}
	\State Set $L:=L\gamma_{\rm inc}$.
	\State Find the largest root $a>0$ of the equation $\frac{a^2}{A_k+a} = 2\frac{1+\sigma A_k}{L}$. \label{a-quad-eq}
	\State Set $y = \frac{A_k x_k +a v_k}{A_k + a}$.
	\State Compute $z=T_{L+\sigma}^\sigma(y)=\argmin_{x}[f(y)+\innprod{\nabla{f}(y)}{x-y}+\frac{L}{2}\norm{x-y}^2 + \varPsi_\sigma(x)]$.
	\State Compute $T_L(z)$ and $T_{L+\sigma}^\sigma(z)$ \label{APG-iter-add-prox}.
	\State Test the conditions
	\begin{subequations}
	\label{APG-iter-test}
	\begin{align}
	&\innprod{\nabla{f}(y)-\nabla{f}(T_{L+\sigma}^\sigma(y))}{y-T_{L+\sigma}^\sigma(y)} \geq \frac{1}{L}\norm{\nabla{f}(y)-\nabla{f}(T_{L+\sigma}^\sigma(y))}^2, \label{APG-iter-test-a}\\
	&\varphi_\sigma(T_{L+\sigma}^\sigma(z)) \leq m_{L+\sigma}^\sigma(z;T_{L+\sigma}^\sigma(z)), \label{APG-iter-test-b}\\
	&\text{[Optional]}~~\varphi(T_L(z)) \leq \varphi(z) \label{APG-iter-test-c}.
	\end{align}
	\end{subequations}
\Until{the conditions in \eqref{APG-iter-test} hold.} \label{APG-iter-loop-e}
\State Define $y_k:=y$, $M_k:=L$, $x_{k+1}:=z=T_{M_k+\sigma}^\sigma(y_k)$, \\
\quad $a_{k+1}:=a$, $A_{k+1}:=A_k+a_{k+1}$, $L_{k+1}:=\max\{L_{\min},M_k/\gamma_{\rm dec}\}$, \label{AGP-iter-upadte}
\State \quad $\psi_{k+1}(x):=\psi_k(x)+a_{k+1}[f(x_{k+1})+\innprod{\nabla{f}(x_{k+1})}{x-x_{k+1}}+\varPsi_\sigma(x)]$.\label{est-seq-formula}
\State Output $\{x_{k+1},\psi_{k+1},M_k,L_{k+1},A_{k+1}\}$.
\end{algorithmic}
\end{algorithm}

\begin{equation}\label{APG-iter-v_k-formula}
v_k = \prox_{\gamma_k\varPsi}(w_k),\text{ where } \gamma_k = \frac{A_k}{1+\sigma A_k},~~w_k = x_0-\frac{1}{1+\sigma A_k}\sum_{i=1}^ka_i \nabla{f}(x_i).
\end{equation}

\begin{algorithm}
\caption{
Proximal Gradient Iteration
\newline
$\{T_{M_k}(x_k), M_k, L_{k+1}\} \leftarrow \PGIter(x_k,L_k)$
}
\label{alg:PG-iter}
\textbf{Parameters:} $\gamma_{\rm inc}>1$, $\gamma_{\rm dec}\geq 1$, $L_{\min} \in ]0,L_f]$.\\
\textbf{Input:} $x_k \in \E$, $L_k > 0$.
\begin{algorithmic}[1]
\State Set $L:=L_k/\gamma_{\rm inc}$.
\Repeat \label{PG-iter-loop-s}
\State Set $L:=\gamma_{\rm inc}L$.
\State Compute $T_L(x_k)$.
\Until{the following condition holds:} \label{PG-iter-loop-e}
\begin{equation}\label{PG-iter-test}
	\varphi(T_L(x_k))\leq m_L(x_k;T_L(x_k)).
\end{equation}
\State Define $M_k:=L$, $L_{k+1}:=\max\{L_{\min},M_k/\gamma_{\rm dec}\}$.
\State Output $\{T_{M_k}(x_k), M_k, L_{k+1}\}$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{
Adaptive Accelerated Proximal Gradient Method
\newline
$\AdaAPG(x_0,L_{-1},\sigma_0,\ep)$
}
\label{alg:AdaAPG}
\textbf{Parameters:} $\gamma_{\rm inc}>1$, $\gamma_{\rm dec}\geq 1$, $L_{\rm min}\in ]0,L_f]$, $\gamma_{\rm reg}>1$, $\beta\in]0,1]$.\\
\textbf{Input:} $x_0 \in \E$, $L_{-1} \in [L_{\min}, \gamma_{\rm inc}L_f]$, $\sigma_0>0$, $\ep>0$.
\begin{algorithmic}[1]
\State $L_{0}:= L_{-1}$.
\For{$j=0,1,2,\ldots$}
	\State $\sigma_j := \sigma_0/\gamma_{\rm reg}^j$.
	\State $\psi_{0}(x):=\frac{1}{2}\norm{x-x_{0}}^2$, $A_{0}:=0$.
	\Repeat{ \textbf{for} $k=0,1,2,\ldots$}
		\State $\{x_{k+1},\psi_{k+1},M_{k},L_{k+1},A_{k+1}\} \leftarrow \APGIter_{\sigma_j}(x_{k},\psi_{k},L_{k},A_{k})$.
		\If{$\norm{g_{M_{k}}(x_{k+1})} \leq \ep$}
			\State output $\{\sigma_j, x_{k+1},T_{M_{k}}(x_{k+1}),M_{k},L_{k+1}\}$ and terminate the algorithm.
		\EndIf
	\Until{$A_{k+1} \geq \frac{2(M_{k}+\sigma_j)}{\beta^2\sigma_j^2}$}.\label{A-growth}
\State $L_{0} := L_{k+1}$.
\EndFor
\end{algorithmic}
\end{algorithm}

In this section, given an initial point $\xinit \in \E$, we assume that the objective function $\varphi$ admits the H\"olderian error bound condition
\begin{equation}\label{HEB-review}
\varphi(x)-\varphi^* \geq \kappa\dist(x,X^*)^\rho,\quad \forall x\in \lev_{\varphi}(\varphi(\xinit)),
\end{equation}
for some $\kappa>0$ and $\rho\geq 1$.

\begin{algorithm}
\caption{
Restart Scheme for Adaptive Accelerated Proximal Gradient Method
\newline
$\rAdaAPG (\xinit,\Linit,\sigmainit,\ep)$
}
\label{alg:rAdaAPG}
\textbf{Parameters:}\\
\quad $\gamma_{\rm inc}>1$, $\gamma_{\rm dec}\geq 1$, $L_{\rm min}\in ]0,L_f]$ (for backtracking line-search);\\
\quad $\gamma_{\rm reg}>1$ (the ratio to decrease the regularization parameter);\\
\quad $\beta\in ]0,1]$  (controls the timing when the current regularization parameter must be decreased);\\
\quad $\theta \in ]0,1[$ (the ratio reducing the residue per iteration).\\
\textbf{Input:} $\xinit \in \E$, $\Linit \in [L_{\min},\gamma_{\rm inc}L_f]$, $\sigmainit>0$, $\ep>0$.
\begin{algorithmic}[1]
\State Compute $\{\outerXplus{0},\outerM{0},\outerL{0}\} \leftarrow \PGIter(\xinit,\Linit)$ \label{rAdaAPG-init}.
\For{$t=0,1,2,\ldots$}
	\State \textbf{if} $\norm{g_{\outerM{t}}(\outerXinit{t})} \leq \ep$ \textbf{then} output $\{\outerXinit{t},\outerM{t},\outerXplus{t}\}$ and terminate the algorithm. \label{rAdaAPG-terminate}
	\State $\outerep{t}:= \theta\norm{g_{\outerM{t}}(\outerXinit{t})}$.
	\State $\{\outersigma{t+1},\outerXinit{t+1},\outerXplus{t+1},\outerM{t+1},\outerL{t+1}\} \leftarrow \AdaAPG(\outerXplus{t},\outerL{t},\outersigma{t},\ep^{(t)})$
	\State (with testing the optional condition \eqref{APG-iter-test-c} of $\APGIter$).
\EndFor
\end{algorithmic}
\end{algorithm}

To describe the iteration complexity bounds, we define $N(\ep,\sigma_*,C)$ and $\bar\sigma$ as follows.
Given $\ep,\sigma_*,C>0$, let $N(\ep,\sigma_*,C):=0$ if $\norm{g_{\outerM{0}}(\xinit)} \leq \ep$ and otherwise
\begin{align}
N(\ep,\sigma_*,C) &
:= \left(1+ \log_{1/\theta}\frac{\norm{g_{\outerM{0}}(\xinit)}}{\ep} + \log_{\gamma_{\rm reg}}\frac{\sigmainit}{\sigma_*}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}\right) \nonumber\\
&\quad +
\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[
\sqrt{\frac{1}{\sigma_*}} - \sqrt{\frac{1}{\sigmainit}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*} 
+ C\sqrt{2\gamma_{\rm inc}L_f}\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}. \label{N-def}
\end{align}

\begin{equation}\label{bar-sigma-def}
\bar\sigma = \left\{
\begin{array}{ll}
\ds
\frac{\theta}{1+\sqrt{2}\beta}
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
\ep^{\frac{\rho-2}{\rho-1}}
& (\text{if } \rho \geq 2),\\[3truemm]
\ds
\frac{\theta}{1+\sqrt{2}\beta}
\kappa^{\frac{2}{\rho}}\left(\frac{L_f}{L_{\min}}+1\right)^{-1}(\varphi(\xinit)-\varphi^*)^{-\frac{2-\rho}{\rho}}
& (\text{if } 1\leq \rho<2).
\end{array}
\right.
\end{equation}

\fbox{(ii) Case $\rho>2$.}
If $\sigmainit < \bar\sigma$, then $\sigma_*$ is defined as $\sigma_*=\sigmainit$. 
Therefore, the latter bound of (ii) is obtained by \eqref{N-ub-basic-HEB}.

Now consider the case $\sigmainit \geq \bar\sigma$.
Then, there exists $t_0 \in \{0,\ldots,T+1\}$ satisfying the conditions in Lemma~\ref{lem:rAdaAPG-sigma-2}.
By \eqref{sigma-bound-rho>2-4}, remark that
\begin{equation}\label{rAdaAPG-compl-p>2-pf-sum}
\sum_{t=t_0}^{T}\sqrt{\theta^{\frac{\rho-2}{\rho-1}(T-t)}}
=
\sum_{i=0}^{T-t_0}\sqrt{\theta^{\frac{\rho-2}{\rho-1}}}^{\,i}
=
\frac{1-\sqrt{\theta^{\frac{\rho-2}{\rho-1}}}^{T-t_0+1}}{1-\sqrt{\theta^{\frac{\rho-2}{\rho-1}}}}
\leq
\frac{1-\sqrt{\theta^{\frac{\rho-2}{\rho-1}}\cdot\dfrac{\bar\sigma}{\outersigma{0}}}}{1-\sqrt{\theta^{\frac{\rho-2}{\rho-1}}}}.
\end{equation}

Therefore, we conclude that
\begin{align*}
\sum_{t=0}^{T}\sqrt{\frac{1}{\outersigma{t+1}}}
&=
\sum_{t=0}^{t_0-1} \sqrt{\frac{1}{\outersigma{t+1}}}+
\sum_{t=t_0}^{T}\sqrt{\frac{1}{\outersigma{t+1}}}
\\
&\leq
t_0 \sqrt{\frac{1}{\outersigma{0}}} +
\sqrt{\frac{\gamma_{\rm reg}}{\bar\sigma}}\sum_{t=t_0}^{T}\sqrt{\theta^{{\frac{\rho-2}{\rho-1}}(T-t)}} & (\text{by } \eqref{sigma-bound-rho>2-1} \text{ and } \eqref{sigma-bound-rho>2-2})\\
&\leq
\sqrt{\frac{1}{\outersigma{0}}}\left(1+\frac{\rho-1}{\rho-2}\log_{1/\theta}\frac{\sigma_*^{(0)}}{\min(\sigma_*^{(0)},\outersigma{0})}\right)\\
&\quad~+
\frac{\sqrt{\gamma_{\rm reg}}}{1-\sqrt{\theta^{\frac{\rho-2}{\rho-1}}}}
\left(
\sqrt{\frac{1}{\bar\sigma}}
-
\sqrt{\theta^{\frac{\rho-2}{\rho-1}
}}
\sqrt{\frac{1}{\outersigma{0}}}
\right) & (\text{by } \eqref{sigma-bound-rho>2-3} \text{ and } \eqref{rAdaAPG-compl-p>2-pf-sum})\\
&=:C.
\end{align*}
With this definition of $C$, Lemma~\ref{lem:rAdaAPG-compl} gives $N \leq N(\ep,\sigma_*,C)$.

Then, Proposition~\ref{prop:APG} (v) implies
$$
\norm{g_{M_{0}}(x_1)} \leq \left(2\sqrt{\frac{M_{0}+\outersigma{t}}{A_1}} + \outersigma{t}\right)\dist(\outerXplus{t},X^*).
$$
Moreover, according to the equation at Line~\ref{a-quad-eq} in Algorithm~\ref{APG-iter}, $A_1$ can be calculated as $A_1=2/M_0$. Now remark that, using $M_0 \leq \gamma_{\rm inc}L_f$ (Proposition~\ref{prop:APG}~(i)), we have
\begin{align*}
2\sqrt{\frac{M_{0}+\outersigma{t}}{A_1}} + \outersigma{t} &= 2\sqrt{\frac{M_0(M_0+\outersigma{t})}{2}} + \outersigma{t}
\leq 2\sqrt{\frac{(M_0+\outersigma{t})^2}{2}} + (M_0+\outersigma{t}) \\&= (1+\sqrt{2})(M_0+\outersigma{t}) \leq (1+\sqrt{2})(\gamma_{\rm inc}L_f + \outersigma{t}).
\end{align*}

Combining them and using \eqref{rAdaAPG-dist-bound}\footnote{Although \eqref{rAdaAPG-dist-bound} is asserted in the case $\outerXplus{t} \not\in X^*$, it trivially holds if $\outerXplus{t} \in X^*$ \emph{unless} $\rho = 1$.}, we conclude that
\begin{align}
\norm{g_{M_{0}}(x_1)}
&\leq
(1+\sqrt{2})(\gamma_{\rm inc}L_f+\outersigma{0})\dist(\outerXplus{t},X^*) \nonumber\\
&\leq
(1+\sqrt{2})(\gamma_{\rm inc}L_f+\outersigma{0})
\left(\frac{1}{\kappa}\right)^{\frac{1}{\rho-1}} \left(\frac{L_f}{L_{\min}}+1\right)^{\frac{1}{\rho-1}}\xi_t^{\frac{1}{\rho-1}}
\nonumber\\
&= \theta\ep_*^{\frac{\rho-2}{\rho-1}}\xi_t^{\frac{1}{\rho-1}}
\label{superlinear-rec}\\
&\leq \theta\xi_t^{\frac{\rho-2}{\rho-1}}\xi_t^{\frac{1}{\rho-1}}=\theta\xi_t = \ep^{(t)},
\nonumber
\end{align}
where the last inequality is due to $\xi_t \leq \ep_*$ for $t \geq T_*$ (and remark $\frac{\rho-2}{\rho-1} < 0$).

In other words, the condition $\norm{g_{\outerM{t}}(\outerXinit{t})} < \ep_*$ must imply $\outerXplus{t}\in X^*$, which also yields $N^{(t)}=1$ and $\outerXinit{t+1}=\outerXplus{t} \in X^*$ by Proposition~\ref{prop:APG}~(v) (then the algorithm terminates at the ($t+1$)-th outer loop).
Therefore, we have
\begin{equation}\label{rho=1:gmap-ep*}
\norm{g_{\outerM{t}}(\outerXinit{t})} \geq \ep_*,\quad 0\leq t \leq T-1.
\end{equation}

To show the latter assertion of (iv), suppose $\ep<\ep_*$. Then, the output $\{\outerXinit{T+1},\outerM{T+1},\outerXplus{T+1}\}$ satisfies $\norm{g_{\outerM{T+1}}(\outerXinit{T+1})} \leq \ep < \ep_*$. Therefore, $\outerXplus{T+1}$ must be optimal.

The proof of Theorem~\ref{thm:rAdaAPG} is completed.
\end{proof}

\begin{lemma}\label{lem:HEB}
Let $\varphi:\E\to\RR\cup\{+\infty\}$ be a proper, lower-semicontinuous, and convex function.
For $x_0 \in \E$, suppose that $\varphi$ satisfies the H\"olderian error bound condition \eqref{HEB} with coefficient $\kappa > 0$ and exponent $\rho \geq 1$.
Then, for every $x \in \lev_{\varphi}(\varphi(x_0))\setminus X^*$, we have
the inequalities
\begin{equation}\label{Loj-ineq}
\kappa \dist(x,X^*)^{\rho-1} \leq \inf\{\norm{g}:g \in \partial\varphi(x)\},\quad
\kappa^{\frac{1}{\rho}} (\varphi(x)-\varphi^*)^{\frac{\rho-1}{\rho}} \leq \inf\{\norm{g}:g \in \partial\varphi(x)\}.
\end{equation}
\end{lemma}

\begin{proof}
Let $x^*$ be the projection of $x$ onto $X^*$, so that $\norm{x-x^*}=\dist(x,X^*)$.
For every $g\in\partial \varphi(x)$, we have
\begin{align*}
\kappa \dist(x,X^*)^\rho
&\leq \varphi(x)-\varphi^*
\leq -\innprod{g}{x^*-x}
\leq \norm{g}\dist(x,X^*)\leq \norm{g}\frac{1}{\kappa^{1/\rho}}(\varphi(x)-\varphi^*)^{1/\rho}.
\end{align*}

