\begin{theorem}\label{thm:AdaAPG}
In $\AdaAPG$, let $N$ be the total number of executions of $\APGIter$.
Denote
\begin{equation}\label{sigma-th}
\sigma(x_0,\ep):=\frac{\ep}{(1+\sqrt{2}\beta)\dist(x_0,X^*)},
\end{equation}
where we let $\sigma(x_0,\ep):=+\infty$ when $x_0 \in X^*$.
Then, the following assertions hold.
\begin{enumerate}[(i)]
\item
The algorithm terminates at the $j$-th outer loop whenever
$\sigma_j \leq \sigma(x_0,\ep)$.
Moreover, we have ${\sigma_j \geq \sigma(x_0,\ep)/\gamma_{\rm reg}}$ for all $j>0$.
%\begin{equation}\label{sigma-j-lb}
%\sigma_j \geq \sigma(x_0,\ep)/\gamma_{\rm reg},\quad \forall j>0.
%\end{equation}

\item
Suppose that the algorithm terminates at $j=\ell$ for some $\ell \geq 0$.
Then, $N$ is at most
\begin{align*}
&\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\sigma_\ell}} - \sqrt{\frac{1}{\sigma_0}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell}+ \left(1+\log_{\gamma_{\rm reg}}\frac{\sigma_0}{\sigma_\ell}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell}\right).
\end{align*}
%
\item
If $\sigma_0\leq \sigma(x_0,\ep)$, then
$
N \leq 2+ \left(\sqrt{\frac{2\gamma_{\rm inc}L_f}{\sigma_0}}+1\right)\log\frac{\gamma_{\rm inc}L_f+\sigma_0}{\beta\sigma_0}.
$

%
\item
If $\sigma_0 \geq \sigma(x_0,\ep)$, then $N$ is at most
\begin{align}
&\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\gamma_{\rm reg}\sqrt{\frac{1}{\sigma(x_0,\ep)}} - \sqrt{\frac{1}{\sigma_0}} \right]\log\left(\frac{\gamma_{\rm reg}\gamma_{\rm inc}L_f}{\beta\sigma(x_0,\ep)}+\frac{1}{\beta}\right) \nonumber\\
&+ \left(2+\log_{\gamma_{\rm reg}}\frac{ \sigma_0}{\sigma(x_0,\ep)}\right)\left[2+\log\left(\frac{\gamma_{\rm reg}\gamma_{\rm inc}L_f}{\beta\sigma(x_0,\ep)}+\frac{1}{\beta}\right)\right] \nonumber\\
=~&
O\left(\sqrt{\frac{L_f\dist(x_0,X^*)}{\ep}}\log \frac{L_f\dist(x_0,X^*)}{\ep} + \log \frac{\sigma_0 \dist(x_0,X^*)}{\ep} \log \frac{L_f\dist(x_0,X^*)}{\ep}\right).
\label{AdaAPG-compl-O}
\end{align}
\end{enumerate}
\end{theorem}

(ii) Since $\sigma_\ell=\sigma_0/\gamma_{\rm reg}^\ell$, we have $\ell = \log_{\gamma_{\rm reg}}\sigma_0/\sigma_\ell$.
Using Lemma~\ref{lem:AdaAPG-loop}, $N$ is bounded as follows.
\begin{align*}
N
&\leq
\sum_{j=0}^\ell \left[
2+ \left(\sqrt{\frac{2\gamma_{\rm inc}L_f}{\sigma_j}}+1\right)\log\frac{\gamma_{\rm inc}L_f+\sigma_j}{\beta\sigma_j}
\right]\\
&\leq 2(\ell+1) + \sqrt{2\gamma_{\rm inc}L_f}\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell}\sum_{j=0}^\ell \sqrt{\frac{1}{\sigma_j}}
+ (\ell+1)\log\frac{\gamma_{\rm inc}L_f+\sigma_\ell}{\beta\sigma_\ell},
\end{align*}
where the second inequality is due to $\sigma_j \geq \sigma_\ell~(\forall j \leq \ell)$.

Note that
\begin{align*}
\sum_{j=0}^\ell \sqrt{\frac{1}{\sigma_j}}
&=
\sum_{j=0}^\ell \sqrt{\frac{1}{\sigma_0/\gamma_{\rm reg}^j}}
=
\sqrt{\frac{1}{\sigma_0}} \sum_{j=0}^\ell \sqrt{\gamma_{\rm reg}}^{j}
=
\sqrt{\frac{1}{\sigma_0}}\frac{\sqrt{\gamma_{\rm reg}}^{\ell+1} -1}{\sqrt{\gamma_{\rm reg}} -1}\\
&=
\sqrt{\frac{1}{\sigma_0}}\frac{\sqrt{\gamma_{\rm reg}}\sqrt{\sigma_0/\sigma_\ell} -1}{\sqrt{\gamma_{\rm reg}} -1}
=
\frac{1}{\sqrt{\gamma_{\rm reg}}-1}\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\sigma_\ell}} - \sqrt{\frac{1}{\sigma_0}}\right].
\end{align*}

In view of (i), the assertions (iii) and (iv) follow by applying (ii) with $\sigma_\ell = \sigma_0$ and $\sigma_\ell \geq \sigma(x_0,\ep)/\gamma_{\rm reg}$, respectively.
The big-$O$ expression \eqref{AdaAPG-compl-O} is obtained by substituting the definition of $\sigma(x_0,\ep)$.
\end{proof}

\begin{lemma}\label{lem:rAdaAPG-base}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds.
In the execution of $\rAdaAPG$, the following assertions hold.
\begin{enumerate}[(i)]
\item $\outerL{t},\outerM{t} \in [L_{\min},\gamma_{\rm inc}L_f]$ for all $t\geq 0$.
\item $\varphi(\outerXplus{t+1}) \leq \varphi(\outerXplus{t}) \leq \cdots \leq \varphi(\outerXplus{0}) \leq \varphi(\xinit)$ for all $t\geq 0$.
\item $t \leq \log_{1/\theta}\dfrac{\norm{g_{\outerM{0}}(\xinit)}}{\norm{g_{\outerM{t}}(\outerXinit{t})}}$ for each $t\geq 0$.
\item Whenever $\outerXplus{t} \not\in X^*$, we have
\begin{equation}\label{rAdaAPG-dist-bound}
\dist(\outerXplus{t},X^*)^{\rho-1} \leq \frac{1}{\kappa}\left(\frac{L_f}{L_{\min}}+1\right)\norm{g_{\outerM{t}}(\outerXinit{t})},
\end{equation}
\begin{equation}\label{rAdaAPG-obj-bound}
(\varphi(\outerXplus{t})-\varphi^*)^{\rho-1} \leq \frac{1}{\kappa}\left(\frac{L_f}{L_{\min}}+1\right)^\rho\norm{g_{\outerM{t}}(\outerXinit{t})}^\rho.
\end{equation}
\end{enumerate}
\end{lemma}

(iv)
Since $\outerXplus{t}=T_{\outerM{t}}(\outerXinit{t})$, Lemma~\ref{lem:gmap} (iii) implies that $g_t:=\nabla{f}(\outerXplus{t})-\nabla{f}(\outerXinit{t})+g_{\outerM{t}}(\outerXinit{t})$ belongs to $\partial{\varphi}(\outerXplus{t})$.
Then,
Lemma~\ref{lem:HEB} shows (note that $\outerXplus{t}$ belongs to $\lev_\varphi(\varphi(\xinit))\setminus X^*$ by (ii))
\begin{align*}
\kappa\dist(\outerXplus{t},X^*)^{\rho-1} &\leq \norm{g_t}
\leq \left(\frac{L_f}{\outerM{t}}+1\right)\norm{g_{\outerM{t}}(\outerXinit{t})}
\leq \left(\frac{L_f}{L_{\min}}+1\right)\norm{g_{\outerM{t}}(\outerXinit{t})},
\end{align*}
where the second inequality is due to Lemma~\ref{lem:gmap} (iii) and the last follows by (i). This shows the assertion \eqref{rAdaAPG-dist-bound}. Similarly, \eqref{rAdaAPG-obj-bound} can be obtained using the latter inequality of \eqref{Loj-ineq}.
\end{proof}

\begin{proof}
Since $\outersigma{t+1}\geq \sigma_*$ for each $t=0,\ldots,T_*$, Theorem~\ref{thm:AdaAPG} (ii) gives the following bound for $t=0,\ldots,T_*$:
\begin{align*}
N^{(t)}
&\leq 
\left(1+\log_{\gamma_{\rm reg}}\frac{\outersigma{t}}{\outersigma{t+1}}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\outersigma{t+1}}{\beta\outersigma{t+1}}\right)\\
&\quad +
\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\outersigma{t+1}}} - \sqrt{\frac{1}{\outersigma{t}}}\right]\log\frac{\gamma_{\rm inc}L_f+\outersigma{t+1}}{\beta\outersigma{t+1}}\\
&\leq
\left(1+\log_{\gamma_{\rm reg}}\frac{\outersigma{t}}{\outersigma{t+1}}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}\right)\\
&\quad +
\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\outersigma{t+1}}} - \sqrt{\frac{1}{\outersigma{t}}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}.
\end{align*}

To estimate the sum $\sum_{t=0}^{T_*}N^{(t)}$, note that
$$
\sum_{t=0}^{T_*}\left(1+\log_{\gamma_{\rm reg}}\frac{\outersigma{t}}{\outersigma{t+1}}\right) = 1+T_*+\log_{\gamma_{\rm reg}}\frac{\outersigma{0}}{\outersigma{T_*+1}} \leq 1+ \log_{1/\theta}\frac{\norm{g_{\outerM{0}}(\xinit)}}{\ep_*} + \log_{\gamma_{\rm reg}}\frac{\outersigma{0}}{\sigma_*},
$$
and
\begin{align*}
\sum_{t=0}^{T_*}
\left[\sqrt{\gamma_{\rm reg}}\sqrt{\frac{1}{\outersigma{t+1}}} - \sqrt{\frac{1}{\outersigma{t}}}\right]
&=
(\sqrt{\gamma_{\rm reg}}-1)\sum_{t=0}^{T_*}\sqrt{\frac{1}{\outersigma{t+1}}}
+\sum_{t=0}^{T_*}
\left[\sqrt{\frac{1}{\outersigma{t+1}}} - \sqrt{\frac{1}{\outersigma{t}}}\right]\\
&=
(\sqrt{\gamma_{\rm reg}}-1)\sum_{t=0}^{T_*}\sqrt{\frac{1}{\outersigma{t+1}}}
+
\sqrt{\frac{1}{\outersigma{T_*+1}}} - \sqrt{\frac{1}{\outersigma{0}}}.
\end{align*}

Therefore, $\sum_{t=0}^{T_*}N^{(t)}$ is bounded by
\begin{align*}
\sum_{t=0}^{T_*}N^{(t)}
&\leq \left(1+ \log_{1/\theta}\frac{\norm{g_{\outerM{0}}(\xinit)}}{\ep_*} + \log_{\gamma_{\rm reg}}\frac{\outersigma{0}}{\sigma_*}\right)\left(2+\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}\right)\\
&\quad +
\frac{\sqrt{2\gamma_{\rm inc}L_f}}{\sqrt{\gamma_{\rm reg}}-1}\left[
\sqrt{\frac{1}{\sigma_*}} - \sqrt{\frac{1}{\outersigma{0}}}\right]\log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*} \\
&\quad + \sqrt{2\gamma_{\rm inc}L_f} \sum_{t=0}^{T_*}\sqrt{\frac{1}{\outersigma{t+1}}} \log\frac{\gamma_{\rm inc}L_f+\sigma_*}{\beta\sigma_*}\\
&=N(\ep_*,\sigma_*,C).
\end{align*}

\begin{lemma}\label{lem:rAdaAPG-sigma}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds.
Suppose that $\rAdaAPG$ terminated with the stopping criterion at the $(T+1)$-th outer loop for some $T\geq 0$.
Let $\bar\sigma$ be defined by \eqref{bar-sigma-def}.
\begin{enumerate}[(i)]
\item
For each $t=0,\ldots,T$, we have
$$
\outersigma{t+1}
\left\{
\begin{array}{ll}
=\outersigma{t}&(\outersigma{t}\leq \sigma(\outerXplus{t},\ep^{(t)})),\\
\geq\sigma(\outerXplus{t},\ep^{(t)})/\gamma_{\rm reg}&(\text{otherwise}),
\end{array}
\right.
$$
where $\sigma(\cdot,\cdot)$ is defined by \eqref{sigma-th}. 

\item It follows that $\sigma(\outerXplus{t},\ep^{(t)}) \geq \bar\sigma$ for all $t=0,\ldots,T$.
%\begin{equation}\label{sigma-th-const}
%\sigma(\outerXplus{t},\ep^{(t)}) \geq \bar\sigma, \quad t=0,\ldots,T.
%\end{equation}
When $\rho \geq 2$, we further obtain
\begin{equation}\label{sigma-th-t}
\sigma(\outerXplus{t},\ep^{(t)}) \geq \frac{\theta^{\frac{1}{\rho-1}}}{1+\sqrt{2}\beta}\cdot
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
(\ep^{(t)})^{\frac{\rho-2}{\rho-1}}
 \geq \bar\sigma,
\end{equation}
for each $t=0,\ldots,T$.
\item
For each $t=0,\ldots,T+1$, we obtain
$$
\outersigma{t} \left\{
\begin{array}{ll}
=\sigmainit & (\sigmainit \leq \bar\sigma),\\
\geq\bar\sigma/\gamma_{\rm reg} & (\text{otherwise}).
\end{array}
\right.
$$
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:rAdaAPG-sigma-2}
Assume that the H\"olderian error bound condition \eqref{HEB-review} holds with $\rho >2$.
Suppose that $\rAdaAPG$ terminated with the stopping criterion at the $(T+1)$-th outer loop for some $T\geq 0$.
If $\sigmainit \geq \bar\sigma$ holds for $\bar\sigma$  defined by \eqref{bar-sigma-def},
then there exists $t_0 \in \{0,\ldots,T+1\}$ such that the following conditions hold, where
$
\sigma_*^{(0)}:=\frac{\theta}{1+\sqrt{2}\beta}\cdot
\kappa^{\frac{1}{\rho-1}}\left(\frac{L_f}{L_{\min}}+1\right)^{-\frac{1}{\rho-1}}
\|g_{\outerM{0}}(\xinit)\|^{\frac{\rho-2}{\rho-1}}.
$
\begin{align}
\text{(i)\qquad} & \outersigma{0}=\cdots=\outersigma{t_0}. \label{sigma-bound-rho>2-1}\\
\text{(ii)\qquad} & \outersigma{t+1} \geq \theta^{-\frac{\rho-2}{\rho-1}(T-t)} \bar\sigma/\gamma_{\rm reg},\quad t=t_0,\ldots,T.\label{sigma-bound-rho>2-2}\\
\text{(iii)\qquad} & t_0 \leq 1+\frac{\rho-1}{\rho-2}\log_{1/\theta}\frac{\sigma_*^{(0)}}{\min(\sigmainit,\sigma_*^{(0)})}.\label{sigma-bound-rho>2-3}\\
\text{(iv)\qquad} & \theta^{\frac{\rho-2}{\rho-1}(T-t_0)} \geq {\bar\sigma}/{\outersigma{0}}.\label{sigma-bound-rho>2-4}
\end{align}

\end{lemma}

Note that $\{\sigma_*^{(t)}\}$ is non-increasing;
in fact, the relation $\ep^{(t+1)}\leq \theta\ep^{(t)}$ implies
\begin{equation}\label{sigma-*-mono}
\sigma_*^{(t+1)}=c(\ep^{(t+1)})^\omega\leq c\theta^\omega(\ep^{(t)})^\omega = \theta^\omega \sigma_*^{(t)} \leq \sigma_*^{(t)}.
\end{equation}
